sendPacket:
function sendPacket(Packet) {
  const traceNavigation =
    globalThis.roNaviDebug?.active &&
    /REQUEST_MOVE2?$|PRIVATE_AIRSHIP_REQUEST$/.test(
      Packet.constructor?.name || "",
    );
  if (traceNavigation)
    globalThis.roNaviDebug.log("network-build", {
      packet: Packet.constructor.name,
      socketPresent: Boolean(_socket),
      socketState: _socket?.readyState,
      isZone: _socket?.isZone,
    });
  const pkt = Packet.build();
  if (traceNavigation)
    globalThis.roNaviDebug.log("network-built", {
      packet: Packet.constructor.name,
      id: "0x" + new DataView(pkt.buffer).getUint16(0, true).toString(16),
      bytes: pkt.buffer.byteLength,
    });
  if (packetDump) {
    const id = new BinaryReader(pkt.buffer).readUShort();
    console.log(
      "%c[Network] Dump Send: \n%cPacket ID: 0x%s\nPacket Name: %s\nLength: %d\nContent:\n%s",
      "color:#007070",
      "color:inherit",
      id.toString(16),
      Packet.constructor.name,
      pkt.buffer.byteLength,
      utilsBufferToHexString(pkt.buffer).toUpperCase(),
    );
  }
  if (packetDump) console.log("%c[Network] Send:", "color:#007070", Packet);
  if (_socket && _socket.isZone) PacketCrypt_default.process(pkt.view);
  send(pkt.buffer);
  if (traceNavigation)
    globalThis.roNaviDebug.log("network-send-returned", {
      socketPresent: Boolean(_socket),
      socketState: _socket?.readyState,
    });
}
